INSERT INTO products (id,name,category,description,price_minor,image,alt,sizes,colors,featured,brand,subcategory,mrp_minor,discount_percent,material,fit,rating_value,rating_scale,rating_count,source_store,source_product_id,canonical_url,verification_status,missing_fields) VALUES ('source-men-003','Veirdo Men’s Pure Cotton Utility Shirt','men','Upgrade your casual wardrobe with the Veirdo Men’s Cotton Utility Shirt, designed for style, comfort, and versatility. Crafted from 100% premium cotton, this shirt ensures a soft, breathable feel that keeps you comfortable all day long. Featuring a modern utility design with dual flap chest pockets, it blends functional detailing with contemporary fashion. Perfect for casual outings, travel, or smart-casual office wear, this shirt pairs effortlessly with jeans or chinos for a polished yet relaxed look. The full sleeves, button-down front, and tailored fit add a refined edge, while the crisp fabric structure maintains shape and durability through every wash. Whether you’re dressing up for a weekend brunch or a casual evening, the Veirdo Cotton Utility Shirt delivers the perfect balance of rugged charm and everyday sophistication.',84900,'https://m.media-amazon.com/images/I/61cFGrX+PtL._SY741_.jpg','Veirdo Men’s Pure Cotton Utility Shirt product image','[]','[]',0,'Veirdo','Men',NULL,NULL,NULL,'Regular Fit','3.8','5.0',130,'Amazon India','B0FV91LFTQ','https://www.amazon.in/Veirdo%C2%AE-Button-Down-Comfortable-Everyday-VD_FS_RC_SH_MRN_S/dp/B0FV91LFTQ','verified_partial','["color","sizes","mrp_inr","discount_percent","material"]') ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,price_minor=excluded.price_minor,image=excluded.image,alt=excluded.alt,sizes=excluded.sizes,colors=excluded.colors,featured=excluded.featured,brand=excluded.brand,subcategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit