INSERT INTO products (id,name,category,description,price_minor,image,alt,sizes,colors,featured,brand,subcategory,mrp_minor,discount_percent,material,fit,rating_value,rating_scale,rating_count,source_store,source_product_id,canonical_url,verification_status,missing_fields) VALUES ('source-women-009','TOPLOT Women’s Printed Co-Ord Set','women','This coord set features a relaxed-fit top with a mandarin collar and button-down front, adorned with an abstract print for a modern touch. The three-quarter sleeves and lightweight fabric enhance comfort and breathability. The accompanying ankle-length trousers offer a structured yet comfortable fit, with a straight-leg cut that complements the top’s flowy silhouette. Paired with chunky sneakers, this set blends casual elegance with contemporary style, perfect for everyday wear.',59900,'https://m.media-amazon.com/images/I/61hiiOxAjML._SY741_.jpg','TOPLOT Women’s Printed Co-Ord Set product image','[]','[]',0,'TOPLOT','Women',NULL,NULL,NULL,'Regular Fit','3.8','5.0',682,'Amazon India','B0DXFBRTDL','https://www.amazon.in/TOPLOT-Button-up-Loose-fit-Artistic-5234_M_Olive/dp/B0DXFBRTDL','verified_partial','["color","sizes","mrp_inr","discount_percent","material"]') ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,price_minor=excluded.price_minor,image=excluded.image,alt=excluded.alt,sizes=excluded.sizes,colors=excluded.colors,featured=excluded.featured,brand=excluded.brand,subcategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit=excluded.fit,rating_value=excluded.rating_value,rating_scale=excluded.rating_scale,rating_count=excluded.rating_count,source_store=excluded.source_store,source_product_id=excluded.source_product_id,canonical_url=excluded.canonical_url,verification_status=excluded.verification_status,missing_fields=excluded.missing_fields;
