INSERT INTO products (id,name,category,description,price_minor,image,alt,sizes,colors,featured,brand,subcategory,mrp_minor,discount_percent,material,fit,rating_value,rating_scale,rating_count,source_store,source_product_id,canonical_url,verification_status,missing_fields) VALUES ('source-women-010','Vastrick Cotton Slub Embroidered Co-Ord Set','women','Upgrade your wardrobe with this elegant Women''s Embroidered Cotton Slub Co-Ord Set from Vastrick Fashion. Crafted from soft and breathable cotton slub fabric, this stylish two-piece outfit features beautiful floral embroidery work that lends it a premium, eye-catching appeal. The relaxed-fit top paired with wide-leg palazzo pants offers unmatched comfort and effortless style, making it a versatile addition to any wardrobe. Whether you are heading out for a casual outing, a festive celebration, a day at the office, or simply going about your daily routine, this co-ord set ensures you look and feel your best. Its lightweight and breathable fabric makes it especially well-suited for warm summer days. The thoughtfully designed silhouette flatters a variety of body types while keeping you at ease throughout the day. A perfect blend of traditional craftsmanship and contemporary fashion, this set lets you make a confident style statement wherever you go.',99900,'https://m.media-amazon.com/images/I/51C6Zwpqu9L._SX679_.jpg','Vastrick Cotton Slub Embroidered Co-Ord Set product image','[]','[]',0,'Vastrick','Women',NULL,NULL,'Cotton Slub','Regular',NULL,NULL,NULL,'Amazon India','B0H6D8Z99S','https://www.amazon.in/Vastrick-Fashion-Embroidered-Embroidery-Regular/dp/B0H6D8Z99S','verified_partial','["color","sizes","mrp_inr","discount_percent","rating"]') ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,price_minor=excluded.price_minor,image=excluded.image,alt=excluded.alt,sizes=excluded.sizes,colors=excluded.colors,featured=excluded.featured,brand=excluded.brand,subcategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit=excluded.fit,rating_value=excluded.rating_value,rating_scale=excluded.rating_scale,rating_count=excluded.rating_count,source_store=excluded.source_store,source_product_id=excluded.source_product_id,canonical_url=excluded.canonical_url,verification_status=excluded.verification_status,missing_fields=excluded.missing_fields;
