INSERT INTO products (id,name,category,description,price_minor,image,alt,sizes,colors,featured,brand,subcategory,mrp_minor,discount_percent,material,fit,rating_value,rating_scale,rating_count,source_store,source_product_id,canonical_url,verification_status,missing_fields) VALUES ('source-footwear-007','Simple and Casual Look Sandal','footwear','Step into Effortless Style with the Simple and Casual Look Sandal Discover the perfect blend of comfort and style with the Simple and Casual Look Sandal, exclusively brought to you by Stepee. Designed for those who value simplicity without compromising on elegance, this sandal is the ideal choice for everyday wear. Whether you&rsquo;re running errands, meeting friends, or enjoying a casual outing, these sandals are your go-to footwear for all-day ease and sophistication. Minimalist Design: Crafted with a sleek and versatile look, these sandals pair effortlessly with any outfit, from jeans to casual dresses. All-Day Comfort: Designed with a comfortable sole and lightweight materials to keep your feet happy, no matter where the day takes you. Durable and Reliable: Made with high-quality materials for long-lasting wear, ensuring value for your money. Easy Slip-On Style: Enjoy the convenience of slipping these on quickly without any hassle, perfect for busy days. Upgrade your footwear collection with a sandal that prioritizes both comfort and style. The Simple and Casual Look Sandal is a must-have for anyone seeking a timeless and versatile addition to their wardrobe. &lt;',59900,'https://cdn2.clevup.in/264522/Black6-1761398698499.jpeg?width=600&format=webp','Simple and Casual Look Sandal product image','[]','[]',0,NULL,'Sandals',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Stepee',NULL,'https://www.stepee.in/products/simple-and-casual-look-sandal-36','verified_partial','["color","sizes","brand","mrp_inr","discount_percent","material","fit","rating","source_product_id"]') ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,price_minor=excluded.price_minor,image=excluded.image,alt=excluded.alt,sizes=excluded.sizes,colors=excluded.colors,featured=excluded.featured,brand=excluded.brand,subcategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit=excluded.fit,rating_value=excluded.rating_value,rating_scale=excluded.rating_scale,rating_count=excluded.rating_count,source_store=excluded.source_store,source_product_id=excluded.source_product_id,canonical_url=excluded.canonical_url,verification_status=excluded.verification_status,missing_fields=excluded.missing_fields;
