INSERT INTO products (id,name,category,description,price_minor,image,alt,sizes,colors,featured,brand,subcategory,mrp_minor,discount_percent,material,fit,rating_value,rating_scale,rating_count,source_store,source_product_id,canonical_url,verification_status,missing_fields) VALUES ('source-footwear-008','Ladies Flat Sandal Style & Everyday Comfort 992001','footwear','Product Specifications Model No.: 992001 Product Type: Ladies Flat Sandal Upper Material: Synthetic Sole Material: PVC Size Range: 36 to 44 Quantity: 1 Pair MRP: ₹330/- Key Features &amp; Benefits Modern Multi-Strap Design: Minimal and stylish everyday look Toe Loop &amp; Elastic Back Strap: Secure, flexible, and comfortable fit Synthetic Upper: Lightweight, durable, and easy to maintain PVC Sole: Flexible, anti-slip, and long-lasting Comfort Fit: Ideal for daily wear and extended use Step into modern elegance with the Ladies Flat Sandal – Model No. 992001, designed for women who love a clean, minimal look with reliable comfort. Perfect for daily wear, casual outings, and summer styling, this sandal offers a stylish yet practical solution for everyday use. Crafted with a durable synthetic upper, this sandal features a sleek multi-strap design with a toe loop and elastic back strap, ensuring a secure fit while adding a contemporary touch. The soft cushioned footbed provides lasting comfort, while the PVC sole ensures flexibility, durability, and a steady grip for daily wear.',33000,'https://sreeleathersonline.com/cdn/shop/files/WhatsAppImage2021-03-09at20.10.21_1_1280x.jpg?v=1761459835','Ladies Flat Sandal Style & Everyday Comfort 992001 product image','[]','[]',0,'Sreeleathers','Sandals',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Sreeleathers',NULL,'https://sreeleathersonline.com/products/ladies-flat-sandal-992001?variant=49233387159798','verified_partial','["color","sizes","mrp_inr","discount_percent","material","fit","rating","source_product_id"]') ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,price_minor=excluded.price_minor,image=excluded.image,alt=excluded.alt,sizes=excluded.sizes,colors=excluded.colors,featured=excluded.featured,brand=excluded.brand,subcategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit=excluded.fit,rating_value=excluded.rating_value,rating_scale=excluded.rating_scale,rating_count=excluded.rating_count,source_store=excluded.source_store,source_product_id=excluded.source_product_id,canonical_url=excluded.canonical_url,verification_status=excluded.verification_status,missing_fields=excluded.missing_fields;
