INSERT INTO products (id,name,category,description,price_minor,image,alt,sizes,colors,featured,brand,subcategory,mrp_minor,discount_percent,material,fit,rating_value,rating_scale,rating_count,source_store,source_product_id,canonical_url,verification_status,missing_fields) VALUES ('source-accessories-007','JI ACCESSORIES Women’s Crossbody Sling Bag','accessories','Discover timeless elegance and modern convenience with our Women’s Stylish Crossbody Sling Bag, crafted from premium quality PU leather that combines durability with a chic, sophisticated look. Designed for everyday use, this lightweight and compact shoulder purse is perfect for women who want functionality without compromising on style. Featuring a spacious main compartment, secure zipper closure, and neatly designed pockets, it helps you keep essentials like your mobile phone, wallet, cards, cosmetics, and keys organized and easily accessible. The adjustable strap allows you to wear it as a crossbody bag or shoulder bag, offering hands-free comfort whether you’re shopping, traveling, attending casual outings, or commuting to work. Its sleek design complements both casual and semi-formal outfits, making it a versatile choice for different occasions. The smooth finish, fine stitching, and stylish design give it a premium touch, while the lightweight build ensures all-day comfort. Ideal for daily use, travel, and gifting, this crossbody sling bag is not just an accessory but a perfect companion for women who value style, convenience, and practicality. Carry it with confidence and add a touch of elegance to your everyday look.',29800,'https://m.media-amazon.com/images/I/719HhNvMzeL._SY535_.jpg','JI ACCESSORIES Women’s Crossbody Sling Bag product image','[]','[]',0,'JI','Accessories',NULL,NULL,NULL,NULL,'4.1','5.0',640,'Amazon India','B0FQPRSNZ1','https://www.amazon.in/JI-ACCESSORIES-Womens-Stylish-Crossbody/dp/B0FQPRSNZ1','verified_partial','["color","sizes","mrp_inr","discount_percent","material","fit"]') ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,price_minor=excluded.price_minor,image=excluded.image,alt=excluded.alt,sizes=excluded.sizes,colors=excluded.colors,featured=excluded.featured,brand=excluded.brand,subcategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit=excluded.fit,rating_value=excluded.rating_value,rating_scale=excluded.rating_scale,rating_count=excluded.rating_count,source_store=excluded.source_store,source_product_id=excluded.source_product_id,canonical_url=excluded.canonical_url,verification_status=excluded.verification_status,missing_fields=excluded.missing_fields;
